import torch, cv2, torchvision.models as models, torchvision.transforms as transforms; from PIL import Image; ls = ["metro21", "metro22", "metro23", "metro25", "metro30000A", "metro31000", "metro32000", "metro400", "metro66", "metro70", "metro80", "series113", "series117", "series189", "series207", "series221", "series223", "series225", "series227", "series271", "series281", "series283", "series285", "series287", "series289", "series321", "series323", "series681", "series683", "series87", "seriesHOT7000"]; model = models.resnet18(num_classes=31); chk = torch.load("models/jr_west_model/model_best.pth.tar", map_location="cpu"); model.load_state_dict(chk["state_dict"]); model.eval(); tf = transforms.Compose([transforms.Resize(256), transforms.CenterCrop(224), transforms.ToTensor(), transforms.Normalize([0.485, 0.456, 0.406], [0.229, 0.224, 0.225])]); img = Image.open("data/jr_west/test_train.jpg").convert("RGB"); out = model(tf(img).unsqueeze(0)); probs = torch.nn.functional.softmax(out, dim=1).squeeze(0); top_p, top_i = torch.topk(probs, k=3); b_name = ls[top_i[0].item()]; b_val = top_p[0].item() * 100; print(f"\n--- AI Identification Result ---\nBest Answer: {b_name} ({b_val:.2f}%)\n"); o_img = cv2.imread("data/jr_west/test_train.jpg"); cv2.putText(o_img, f"{b_name} ({b_val:.1f}%)", (20, 40), cv2.FONT_HERSHEY_SIMPLEX, 0.8, (0, 255, 0), 2, cv2.LINE_AA) if o_img is not None else None; cv2.imwrite("data/jr_west/result_train.jpg", o_img) if o_img is not None else None; print("Saved result image successfully: data/jr_west/result_train.jpg\n")
